begin;

delete from public.version_banners vb
using public.game_versions gv, public.games g
where vb.version_id=gv.id and gv.game_id=g.id and g.code='YYS'
  and gv.version_no between 'YYS-2016-01-01' and 'YYS-2018-12-31';

with yys as (select id from public.games where code='YYS' limit 1),
payload as (select $json$[{"version_no":"YYS-2016-09-09","version_name":"国服全平台公测","start_date":"2016-09-09","note":"《阴阳师》国服全平台公测开启；作为GUCC历史版本档案起点。","banners":[]},{"version_no":"YYS-2016-09-15","version_name":"历史更新｜络新妇登场","start_date":"2016-09-15","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"络新妇","banner_type":"standard_addition"}]},{"version_no":"YYS-2016-10-01","version_name":"历史更新｜妖刀姬·樱花妖登场","start_date":"2016-10-01","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"妖刀姬","banner_type":"pickup"},{"character":"樱花妖","banner_type":"standard_addition"}]},{"version_no":"YYS-2016-11-11","version_name":"魑魅之卷","start_date":"2016-11-11","note":"早期大型资料片/内容更新，新增一目连、般若。","banners":[{"character":"一目连","banner_type":"pickup"},{"character":"般若","banner_type":"standard_addition"}]},{"version_no":"YYS-2016-12-25","version_name":"历史更新｜青坊主登场","start_date":"2016-12-25","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"青坊主","banner_type":"standard_addition"}]},{"version_no":"YYS-2016-12-30","version_name":"历史更新｜花鸟卷·夜叉登场","start_date":"2016-12-30","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"花鸟卷","banner_type":"pickup"},{"character":"夜叉","banner_type":"standard_addition"},{"character":"古笼火","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-01-13","version_name":"历史更新｜黑童子·白童子登场","start_date":"2017-01-13","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"黑童子","banner_type":"standard_addition"},{"character":"白童子","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-01-22","version_name":"历史更新｜辉夜姬·烟烟罗登场","start_date":"2017-01-22","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"辉夜姬","banner_type":"pickup"},{"character":"烟烟罗","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-03-16","version_name":"历史更新｜荒·金鱼姬登场","start_date":"2017-03-16","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"荒","banner_type":"pickup"},{"character":"金鱼姬","banner_type":"standard_addition"},{"character":"万年竹","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-04-28","version_name":"历史更新｜鸩·以津真天登场","start_date":"2017-04-28","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"鸩","banner_type":"standard_addition"},{"character":"以津真天","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-05-20","version_name":"历史更新｜彼岸花·匣中少女登场","start_date":"2017-05-20","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"彼岸花","banner_type":"pickup"},{"character":"匣中少女","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-06-24","version_name":"历史更新｜小松丸登场","start_date":"2017-06-24","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"小松丸","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-07-28","version_name":"历史更新｜书翁·兔丸登场","start_date":"2017-07-28","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"书翁","banner_type":"standard_addition"},{"character":"兔丸","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-09-27","version_name":"一周年庆典版本","start_date":"2017-09-27","note":"国服一周年核心内容更新。","banners":[{"character":"玉藻前","banner_type":"pickup"},{"character":"雪童子","banner_type":"pickup"},{"character":"百目鬼","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-11-01","version_name":"历史更新｜数珠登场","start_date":"2017-11-01","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"数珠","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-11-08","version_name":"历史更新｜追月神登场","start_date":"2017-11-08","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"追月神","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-11-11","version_name":"奴良陆生联动","start_date":"2017-11-11","note":"《滑头鬼之孙》联动角色奴良陆生登场。","banners":[{"character":"奴良陆生","banner_type":"collab"}]},{"version_no":"YYS-2017-12-06","version_name":"历史更新｜日和坊登场","start_date":"2017-12-06","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"日和坊","banner_type":"standard_addition"}]},{"version_no":"YYS-2017-12-20","version_name":"历史更新｜御馔津登场","start_date":"2017-12-20","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"御馔津","banner_type":"pickup"}]},{"version_no":"YYS-2017-12-27","version_name":"年末式神更新","start_date":"2017-12-27","note":"新增弈、小袖之手及首批呱太式神。","banners":[{"character":"弈","banner_type":"standard_addition"},{"character":"小袖之手","banner_type":"standard_addition"},{"character":"彼岸花呱","banner_type":"standard_addition"},{"character":"荒呱","banner_type":"standard_addition"},{"character":"辉夜姬呱","banner_type":"standard_addition"},{"character":"花鸟卷呱","banner_type":"standard_addition"},{"character":"一目连呱","banner_type":"standard_addition"},{"character":"妖刀姬呱","banner_type":"standard_addition"},{"character":"青行灯呱","banner_type":"standard_addition"},{"character":"茨木呱","banner_type":"standard_addition"},{"character":"小鹿男呱","banner_type":"standard_addition"},{"character":"两面佛呱","banner_type":"standard_addition"},{"character":"阎魔呱","banner_type":"standard_addition"},{"character":"荒川呱","banner_type":"standard_addition"},{"character":"酒吞呱","banner_type":"standard_addition"},{"character":"大天狗呱","banner_type":"standard_addition"}]},{"version_no":"YYS-2018-02-07","version_name":"春节版本｜山风·卖药郎联动","start_date":"2018-02-07","note":"春节内容更新，并开启《怪化猫》联动角色卖药郎。","banners":[{"character":"山风","banner_type":"pickup"},{"character":"卖药郎","banner_type":"collab"},{"character":"薰","banner_type":"standard_addition"},{"character":"虫师","banner_type":"standard_addition"}]},{"version_no":"YYS-2018-04-04","version_name":"鬼灯联动","start_date":"2018-04-04","note":"《鬼灯的冷彻》联动。","banners":[{"character":"鬼灯","banner_type":"collab"},{"character":"阿香","banner_type":"collab"},{"character":"蜜桃&芥子","banner_type":"collab"}]},{"version_no":"YYS-2018-04-27","version_name":"历史更新｜猫掌柜登场","start_date":"2018-04-27","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"猫掌柜","banner_type":"standard_addition"}]},{"version_no":"YYS-2018-05-16","version_name":"历史更新｜面灵气登场","start_date":"2018-05-16","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"面灵气","banner_type":"pickup"}]},{"version_no":"YYS-2018-07-11","version_name":"犬夜叉联动","start_date":"2018-07-11","note":"《犬夜叉》联动。","banners":[{"character":"犬夜叉","banner_type":"collab"},{"character":"杀生丸","banner_type":"collab"}]},{"version_no":"YYS-2018-08-15","version_name":"刀鸣散华","start_date":"2018-08-15","note":"鬼切主题大型内容更新。","banners":[{"character":"鬼切","banner_type":"pickup"}]},{"version_no":"YYS-2018-09-19","version_name":"二周年庆典版本","start_date":"2018-09-19","note":"国服二周年核心内容更新，SSR白藏主与SP少羽大天狗登场。","banners":[{"character":"白藏主","banner_type":"pickup"},{"character":"少羽大天狗","banner_type":"pickup"}]},{"version_no":"YYS-2018-10-06","version_name":"历史更新｜人面树登场","start_date":"2018-10-06","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"人面树","banner_type":"standard_addition"}]},{"version_no":"YYS-2018-10-17","version_name":"犬夜叉联动·桔梗","start_date":"2018-10-17","note":"","banners":[{"character":"桔梗","banner_type":"collab"}]},{"version_no":"YYS-2018-10-24","version_name":"历史更新｜於菊虫登场","start_date":"2018-10-24","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"於菊虫","banner_type":"standard_addition"}]},{"version_no":"YYS-2018-11-07","version_name":"历史更新｜炼狱茨木童子登场","start_date":"2018-11-07","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"炼狱茨木童子","banner_type":"pickup"}]},{"version_no":"YYS-2018-11-14","version_name":"历史更新｜一反木绵·入殓师登场","start_date":"2018-11-14","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"一反木绵","banner_type":"standard_addition"},{"character":"入殓师","banner_type":"standard_addition"}]},{"version_no":"YYS-2018-12-19","version_name":"历史更新｜天井下登场","start_date":"2018-12-19","note":"GUCC历史归档标签：该日期为明确的内容/式神更新节点；未把未核实的宣传口号伪装成官方版本名。","banners":[{"character":"天井下","banner_type":"standard_addition"}]},{"version_no":"YYS-2018-12-26","version_name":"八岐大蛇降临","start_date":"2018-12-26","note":"","banners":[{"character":"八岐大蛇","banner_type":"pickup"}]}]$json$::jsonb data),
vr as (select x from payload cross join lateral jsonb_array_elements(data) x),
upserted as (
  insert into public.game_versions(game_id,version_no,version_name,start_date,note)
  select yys.id,x->>'version_no',x->>'version_name',(x->>'start_date')::date,nullif(x->>'note','')
  from yys cross join vr
  on conflict(game_id,version_no) do update set version_name=excluded.version_name,start_date=excluded.start_date,note=excluded.note,updated_at=now()
  returning id,version_no
),
br as (select x->>'version_no' version_no,b from vr cross join lateral jsonb_array_elements(coalesce(x->'banners','[]'::jsonb)) b)
insert into public.version_banners(version_id,phase,banner_type,character_id,character_name_raw)
select u.id,case when br.b->>'banner_type'='standard_addition' then 'standard' else 'other' end,br.b->>'banner_type',c.id,br.b->>'character'
from br join upserted u using(version_no)
left join public.characters c on c.game_id=(select id from yys) and c.name=br.b->>'character';

commit;
